-- POEM 2.7.1: Pakistan reference geography and volunteer address/UC profile fields.
-- The seeded hierarchy is based on the project-supplied 2026 reference list.

-- Jurisdictions without an administrative division (currently ICT in the supplied reference)
-- may attach a district directly to the province/territory root.
create or replace function public.save_geography(p_id uuid,p_parent uuid,p_kind text,p_name text,p_code text,p_source text,p_active boolean) returns uuid language plpgsql security definer set search_path='' as $$
 declare result_id uuid; current_row public.geographies; parent_kind text;
 begin
 if not app_private.can_manage_ngos() then raise exception 'POEM admin access required'; end if;
 if app_private.geo_rank(p_kind) is null or length(trim(p_name)) not between 2 and 120 or length(trim(p_code)) not between 1 and 80 or length(p_source)>1000 or p_active is null then raise exception 'Invalid geography'; end if;
 if p_kind='province' and p_parent is not null then raise exception 'Province / territory cannot have a parent'; end if;
 if p_kind<>'province' then
   select kind into parent_kind from public.geographies where id=p_parent;
   if parent_kind is null then raise exception 'Invalid parent level'; end if;
   if not ((p_kind='district' and parent_kind in ('province','division')) or (p_kind<>'district' and app_private.geo_rank(parent_kind)=app_private.geo_rank(p_kind)-1)) then raise exception 'Invalid parent level'; end if;
 end if;
 if p_active and p_parent is not null and not app_private.geo_active(p_parent) then raise exception 'Parent hierarchy is inactive'; end if;
 if p_id is null then
   insert into public.geographies(parent_id,kind,name,code,source_note,active) values(p_parent,p_kind,trim(p_name),trim(p_code),p_source,p_active) returning id into result_id;
 else
   select * into current_row from public.geographies where id=p_id for update;
   if not found then raise exception 'Area not found'; end if;
   if current_row.parent_id is distinct from p_parent or current_row.kind<>p_kind then raise exception 'Existing areas cannot be moved to a different parent or level'; end if;
   update public.geographies set name=trim(p_name),code=trim(p_code),source_note=p_source,active=p_active where id=p_id returning id into result_id;
 end if;
 insert into public.audit_events(actor_id,action,detail) values(auth.uid(),'geography_saved',jsonb_build_object('id',result_id,'name',p_name,'active',p_active)); return result_id;
 end; $$;

-- Preserve the existing profile implementation behind a new public validation wrapper.
alter function public.save_my_profile(jsonb,boolean,integer,uuid) set schema app_private;
alter function app_private.save_my_profile(jsonb,boolean,integer,uuid) rename to save_profile_geo_v12;
revoke all on function app_private.save_profile_geo_v12(jsonb,boolean,integer,uuid) from public,anon,authenticated;
create function public.save_my_profile(p_details jsonb,p_submit boolean,p_version integer,p_geography uuid) returns void language plpgsql security definer set search_path='' as $$
 declare clean_details jsonb; address_value text:=trim(coalesce(p_details->>'address','')); uc_value text:=trim(coalesce(p_details->>'union_council','')); selected_kind text;
 begin
 if jsonb_typeof(p_details)<>'object' or octet_length(p_details::text)>12000 then raise exception 'Invalid profile'; end if;
 if exists(select 1 from jsonb_object_keys(p_details) k where k not in ('full_name','phone','area','address','union_council','education','skills','languages','experience','availability','preference','transport','smartphone','preferred_areas','references','bio')) then raise exception 'Unsupported profile field'; end if;
 if length(address_value)>2000 or length(uc_value)>200 then raise exception 'Address or Union Council is too long'; end if;
 if p_submit then
   if length(address_value)<5 then raise exception 'Full address is required'; end if;
   select kind into selected_kind from public.geographies where id=p_geography and app_private.geo_active(id);
   if selected_kind is distinct from 'taluka' then raise exception 'Select a Taluka / Tehsil before submitting'; end if;
 end if;
 clean_details := (p_details - 'address' - 'union_council' - 'area') || jsonb_build_object('area',address_value);
 perform app_private.save_profile_geo_v12(clean_details,p_submit,p_version,p_geography);
 update public.volunteer_profiles set details=details || jsonb_build_object('address',address_value,'union_council',uc_value) where user_id=auth.uid();
 end; $$;
revoke all on function public.save_my_profile(jsonb,boolean,integer,uuid) from public,anon,authenticated;
grant execute on function public.save_my_profile(jsonb,boolean,integer,uuid) to authenticated;

-- Seed helper. Codes are deterministic and isolated from admin-created geography codes.
create function app_private.seed_reference_geo(p_code text,p_parent_code text,p_kind text,p_name text,p_source text) returns uuid language plpgsql security definer set search_path='' as $$
 declare parent_uuid uuid; result uuid;
 begin
 if p_parent_code is not null then select id into parent_uuid from public.geographies where code=p_parent_code; if parent_uuid is null then raise exception 'Missing reference parent %',p_parent_code; end if; end if;
 insert into public.geographies(parent_id,kind,name,code,source_note,active) values(parent_uuid,p_kind,p_name,p_code,p_source,true)
 on conflict(code) do update set parent_id=excluded.parent_id,kind=excluded.kind,name=excluded.name,source_note=excluded.source_note,active=true returning id into result;
 return result;
 end; $$;
revoke all on function app_private.seed_reference_geo(text,text,text,text,text) from public,anon,authenticated;

